import { Component } from '@angular/core';
import { IonicPage, NavController } from 'ionic-angular';
import { InAppBrowser } from '@ionic-native/in-app-browser';
import { ImpostazioneProvider } from "../../providers/impostazione/impostazione";

/**
 * The Welcome Page is a splash page that quickly describes the app,
 * and then directs the user to create an account or log in.
 * If you'd like to immediately put the user onto a login/signup page,
 * we recommend not using the Welcome page.
*/
@IonicPage()
@Component({
    selector: 'page-welcome',
    templateUrl: 'welcome.html'
})

export class WelcomePage {

    constructor(
        private readonly impostazioneProvider: ImpostazioneProvider,
        public navCtrl: NavController,
        private iab: InAppBrowser
        ) { }


    ionViewDidEnter() {
        this.impostazioneProvider.initProvider().then(() => this.impostazioneProvider.filter()
            .then((settings) => {
                    var count = 0;
                    for (let el in settings) {
                        let row = settings[el];
                        count++;
                        //console.log(row)
                        break;
                    }
                    if(!count){
                        this.navCtrl.setRoot('ImpostazioniPage', {}, { animate: true, direction: 'forward' });
                    }
                }
            )
        )
    }

    gotoNews() {
        this.navCtrl.push('NewsPage'); 
    }
    gotoCalendario() {
        this.navCtrl.push('CalendarioPage'); 
    }
    gotoVocabolario() {
        this.navCtrl.push('VocabolarioPage'); 
    }
    gotoEcosportelli() {
        this.navCtrl.push('EcosportelliPage'); 
    }
    gotoEcopiazzole() {
        this.navCtrl.push('EcopiazzolePage'); 
    }
    gotoSegnalazioni() {
        this.navCtrl.push('SegnalazioniPage'); 
    }
    gotoContatti() {
        this.navCtrl.push('ContattiPage'); 
    }
    gotoContarina() {
        let browser = this.iab.create('http://contarina.it', '_system'); //For system browser, you'll be prompt to choose your browser if you have more than one
        //let browser = new InAppBrowser('url', '_blank'); //For webview,
    }
    gotoSettings() {
        this.navCtrl.push('ImpostazioniPage'); 
    }
}



